1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
wifi: rtw88: check for PCI upstream bridge existence

pci_upstream_bridge() returns NULL if the device is on a root bus.  If
8821CE is installed in the system with such a PCI topology, the probing
routine will crash.  This has probably been unnoticed as 8821CE is mostly
supplied in laptops where there is a PCI-to-PCI bridge located upstream
from the device.  However the card might be installed on a system with
different configuration.

Check if the bridge does exist for the specific workaround to be applied.

Found by Linux Verification Center (linuxtesting.org) with Svace static
analysis tool.

Fixes: 24f5e38a13b5 ("rtw88: Disable PCIe ASPM while doing NAPI poll on 8821CE")
Cc: stable@vger.kernel.org
Signed-off-by: Fedor Pchelkin <pchelkin@ispras.ru>
Acked-by: Ping-Ke Shih <pkshih@realtek.com>
Signed-off-by: Ping-Ke Shih <pkshih@realtek.com>
Link: https://patch.msgid.link/20260220094730.49791-1-pchelkin@ispras.ru

Here is the root cause:
The code assumes `pci_upstream_bridge()` always returns a valid pointer, but it returns NULL when the PCI device is on a root bus. Without a NULL check, dereferencing `bridge->vendor` causes a NULL pointer dereference and a crash during probing of the 8821CE wireless card in such PCI topologies.

Here is the patch:

 int rtw_pci_probe(struct pci_dev *pdev,
 		  const struct pci_device_id *id)
 {
 	struct pci_dev *bridge = pci_upstream_bridge(pdev);
 	struct ieee80211_hw *hw;
 	struct rtw_dev *rtwdev;
 	struct rtw_pci *rtwpci;
 	int drv_data_size;
 	int ret;

 	drv_data_size = sizeof(struct rtw_dev) + sizeof(struct rtw_pci);
 	hw = ieee80211_alloc_hw(drv_data_size, &rtw_ops);
 	if (!hw) {
 		dev_err(&pdev->dev, "failed to allocate hw\n");
 		return -ENOMEM;
 	}

 	rtwdev = hw->priv;
 	rtwdev->hw = hw;
 	rtwdev->dev = &pdev->dev;
 	rtwdev->chip = (struct rtw_chip_info *)id->driver_data;
 	rtwdev->hci.ops = &rtw_pci_ops;
 	rtwdev->hci.type = RTW_HCI_TYPE_PCIE;

 	rtwpci = (struct rtw_pci *)rtwdev->priv;
 	atomic_set(&rtwpci->link_usage, 1);

 	ret = rtw_core_init(rtwdev);
 	if (ret)
 		goto err_release_hw;

 	rtw_dbg(rtwdev, RTW_DBG_PCI,
 		"rtw88 pci probe: vendor=0x%4.04X device=0x%4.04X rev=%d\n",
 		pdev->vendor, pdev->device, pdev->revision);

 	ret = rtw_pci_claim(rtwdev, pdev);
 	if (ret) {
 		rtw_err(rtwdev, "failed to claim pci device\n");
 		goto err_deinit_core;
 	}

 	ret = rtw_pci_setup_resource(rtwdev, pdev);
 	if (ret) {
 		rtw_err(rtwdev, "failed to setup pci resources\n");
 		goto err_pci_declaim;
 	}

 	ret = rtw_pci_napi_init(rtwdev);
 	if (ret) {
 		rtw_err(rtwdev, "failed to setup NAPI\n");
 		goto err_pci_declaim;
 	}

 	ret = rtw_chip_info_setup(rtwdev);
 	if (ret) {
 		rtw_err(rtwdev, "failed to setup chip information\n");
 		goto err_destroy_pci;
 	}

 	/* Disable PCIe ASPM L1 while doing NAPI poll for 8821CE */
-	if (rtwdev->chip->id == RTW_CHIP_TYPE_8821C && bridge->vendor == PCI_VENDOR_ID_INTEL)
+	if (rtwdev->chip->id == RTW_CHIP_TYPE_8821C &&
+	    bridge && bridge->vendor == PCI_VENDOR_ID_INTEL)
 		rtwpci->rx_no_aspm = true;

 	rtw_pci_phy_cfg(rtwdev);

 	ret = rtw_register_hw(rtwdev, hw);
 	if (ret) {
 		rtw_err(rtwdev, "failed to register hw\n");
 		goto err_destroy_pci;
 	}

 	ret = rtw_pci_request_irq(rtwdev, pdev);
 	if (ret) {
 		ieee80211_unregister_hw(hw);
 		goto err_destroy_pci;
 	}

 	return 0;

 err_destroy_pci:
 	rtw_pci_napi_deinit(rtwdev);
 	rtw_pci_destroy(rtwdev, pdev);

 err_pci_declaim:
 	rtw_pci_declaim(rtwdev, pdev);

 err_deinit_core:
 	rtw_core_deinit(rtwdev);

 err_release_hw:
 	ieee80211_free_hw(hw);

 	return ret;
 }
 EXPORT_SYMBOL(rtw_pci_probe);


